<p class="lead">Compare TAMRA against three baselines on identical, isolated inputs. Simulated outcomes are labeled and do not establish real-world performance.</p>
<div class="dashboard-grid"><article class="panel"><h2>Create a simulated dataset</h2><form data-api="/api/research/datasets"><?php field('name','Dataset name','text','','required');field('donations','Donation count','number',100,'required min="1" max="500"');field('receivers','Receiver count','number',20,'required min="1" max="100"');field('seed','Dataset seed','number',42,'required min="0" max="2147483647"');formend('Generate reproducible dataset'); ?></article><article class="panel"><h2>Run a comparison</h2><?php if ($data['datasets']): ?><form data-api="/api/research/experiments"><?php field('name','Experiment name','text','','required');choice('dataset_id','Dataset',array_column($data['datasets'],'name','id'));choice('configuration_id','TAMRA configuration',array_column($data['configurations'],'version','id'));field('seed','Shared outcome seed','number',42,'required min="0" max="2147483647"');formend('Run all four approaches'); ?><?php else: ?><p class="empty-state">Generate a dataset first.</p><?php endif ?></article></div>
<article class="panel spaced"><h2>Experiment history</h2><?php if (!$data['experiments']): ?><p>No experiments yet. No results are fabricated.</p><?php endif ?><ul class="activity-list"><?php foreach ($data['experiments'] as $experiment): ?><li><a class="underlined" href="/experiments/<?= e($experiment['id']) ?>"><?= e($experiment['name']) ?> · <?= e($experiment['dataset_name']) ?></a><?php stamp($experiment['created_at']); ?></li><?php endforeach ?></ul></article>
<article class="panel spaced"><h2>Dataset registry</h2><?php foreach ($data['datasets'] as $dataset): ?><details><summary><?= e($dataset['name']) ?> · <?= e($dataset['source']) ?></summary><pre><?= e(json_encode(json_decode($dataset['metadata'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre><p>SHA-256: <code><?= e($dataset['content_hash']) ?></code></p></details><?php endforeach ?></article>
<article class="panel spaced"><h2>Import anonymized or permitted pilot scenarios</h2><p>Use the documented anonymous dataset schema. Names, emails, addresses and free-text fields are rejected. Metadata must state collection period, permission and limitations.</p><form data-api="/api/research/datasets/import"><?php field('name','Dataset name','text','','required');choice('source','Source',['anonymized'=>'Anonymized historical','pilot'=>'Permitted pilot']);field('collection_period','Collection period','text','','required');field('permission_status','Permission / consent record reference','text','','required');field('limitations','Limitations','textarea','','required');field('preprocessing','Preprocessing and missing-value handling','textarea','','required');field('payload','Anonymous scenario JSON','textarea','','required');formend('Validate and import dataset'); ?></article>
<article class="panel spaced"><h2>Version a TAMRA configuration</h2><?php require BASE_PATH . '/resources/views/algorithm-form.php'; ?></article>
